T[43609]="Um soldado morto, com a carne retirada dos ossos."
T[43610]="Um elmo usado da Aliança."
T[43616]="Um peitoral da Aliança perfurado."
T[43627]="Grom, que você descanse em paz, velho amigo."
T[43628]="Arthas, meu amor, por favor volte para mim."
T[43629]="O jovem Arthas precisa aprender a ter paciência para controlar seu poder. Rezarei para que um dia ele aprenda a liderar com zelo e não com força."
T[43630]="É meu maior desejo que meu amado Taelan cresça e fique forte o suficiente para defender o povo que ele tanto ama."
T[43631]="Desejos são passatempos de tolos. Pegue esta moeda como pagamento pelo seu precioso Olho."
T[43632]="Espero que minhas irmãs e eu possamos crescer e nos casar juntas. Essa moeda parece ser muito antiga."
T[43633]="Aquela jovem aprendiz Jaina é bem atraente para uma humana. Espero que ela reconheça minha elegância e meu poder."
T[43634]="Ouça, querida fonte dos desejos. Você me dará todo o seu poder se sabe o que é bom para você."
T[43635]="Algumas vezes... eu... só... queria um abraço!"
T[43636]="Só uma vez eu queria que alguém me cumprimentasse e não fizesse piadas estúpidas sobre gnomos e viagens no tempo."
T[43637]="Brann Barbabronze esteve aqui."
T[43638]="Espero poder um dia me aposentar e morar na minha casinha com um monte de cachorros pra me fazer companhia."
T[43639]="Eu já tenho um reino inteiro em meu futuro, uma terra para governar. O que mais posso desejar? Talvez um sorvete bem gelado..."
T[43640]="Eu queria saber como você sobreviveu à minha ira, fontezinha."
T[43641]="Eu queria crescer logo. Não vejo a hora de passar dos dez anos."
T[43643]="Espero que meu pai e meus irmãos vivam mais do que eu. Eu não serei um bom rei."
T[43644]="Eu sou tão esquecido! Eu queria ter uma memória melhor. Pera aí, eu já não joguei uma moeda aqui?"
T[43645]="Parece que alguém tentou pescar nessa fonte. Quem faria uma coisa dessas?"
T[43651]="Só de pegar a caneca, você começa a tremer de emoção. É certamente a coisa mais incrível que já viu."
T[43653]="Pequenas marcas de dente podem ser vistas na carcaça."
T[43658]="A lima está um pouco esverdeada."
T[43659]="A ponta desse estoque mostra que os lucros foram altos este ano."
T[43662]="Você esperava que este machado fosse extremamente afiado, certo? Mas não é. Os vraikalen devem confiar em sua força imensa para cortar seus inimigos com ele mesmo assim."
T[43665]="Um fim trágico para uma história triste. Se ao menos os abusos de Malygos não tivessem deixado Keristrasza louca..."
T[43668]="Você não sabe bem o que pensar disto. Ele definitivamente ferve de tanta magia arcana, mas como uma coisa tão pequena pode ser tão importante?"
T[43669]="A única lembrança que o rei Ymiron possuía de seu amor, a rainha Angerboda."
T[43670]="Parece ter perdido todo o mojo depois da morte de seu dono."
T[43675]="A Guerra das Areias Cambiantes... Eu gostaria de esquecer que ela um dia aconteceu."
T[43676]="Por que você não olha pra mim? Abbendis, eu iria para qualquer lugar com você. Como eu gostaria que você olhasse pra mim..."
T[43677]="Como será que essa fonte funciona? Será que eu consigo construir uma?"
T[43678]="Dê-me a força para aceitar as coisas que não posso mudar, a coragem para mudar as coisas que eu posso mudar e a sabedoria para diferenciar umas das outras."
T[43679]="Que a Luz Sagrada nos proteja em nossa viagem ao Norte gelado."
T[43680]="Eu gostaria que a revolta em minha cidade natal fosse contida rapidamente. Eu não quero que ninguém saia ferido."
T[43681]="Que o meu filho Arthas sempre aja pensando no melhor para seu povo."
T[43682]="Espero que o jovem Kael'thas entenda que um dia ele deverá liderar o nosso povo."
T[43683]="Turalyon e Alleria, onde quer que vocês estejam, que estejam bem."
T[43684]="<Você sente o ressoar de três tons distintos em sua cabeça, sendo que o terceiro é quase inaudível sob os outros.>"
T[43685]="Onde está o Ilidan?"
T[43686]="Que minhas irmãs descubram seu verdadeiro potencial e que o nome Correventos seja conhecido como resultado de seus feitos."
T[43687]="Eu queria mesmo é que esses magos tirassem as mãos dos bolsos e as enfiassem nos... livros."
T[43693]="É difícil acreditar que isso seja tudo o que restou do outrora poderoso deus rinoceronte."
T[43694]="Parece que cair no pote de sopa não funcionou tão bem quanto ele esperava."
T[43695]="Também é útil para remover tinta."
T[43696]="Também é útil para remover tinta."
T[43697]="Que coisa estranha! Deve ser um dos objetos mais alienígenas que você já viu."
T[43698]="Ensina a evocar esta mascote."
T[43699]="Tem alguma informação nesta coisa? Como? Não tem nada escrito!"
T[43701]="Eu queria ter o serviço daquele meu primo que só fica cortando madeira o dia todo sem se preocupar..."
T[43702]="Espero um dia poder mostrar o caminho da Luz para o povo e ensinar-lhe o valor das Três Virtudes."
T[43703]="Eu desejo que minha filha seja feliz e aceita. Ela parece tão deslocada aqui..."
T[43704]="Alguém pode me dar uma sela mais confortável? Minhas ancas doem."
T[43705]="Eu queria que um troll morresse... AGORA."
T[43706]="Eu desejo que aquele idiota do Arthas afunde numa grande pilha de esterco de magnatauro!"
T[43707]="Que a missão de Tirion aqui em Nortúndria seja bem sucedida, ou que ao menos ele morra de forma honrosa."
T[43708]="A vida de ladino é dura. Desejo um dia poder me dedicar à minha verdadeira paixão..."
T[43709]="Eu desejo aparecer em outro livro algum dia."
T[43710]="Ah, as fontes de Guilnéas poderiam realizar dez vezes mais desejos do que as de Dalaran!"
T[43711]="Eu queria ter meu pai de volta..."
T[43712]="Minhas preces vão para meus irmãos e irmãs que ainda sofrem no coração de Grim Batol. Eu VOU libertá-los."
T[43713]="Bum. Bum agora? Eu desejo um bum. Vai bum! Essa moeda deve estar quebrada. Será que ela explode?"
T[43714]="Queria ter guardado aquela moeda..."
T[43715]="Só uma vez, é tudo o que eu peço. Só uma vez, deixe a garota vir comigo..."
T[43716]="Gostaria que a água de Nortúndria não fosse tão gelada. Faz com que eu me sinta sonolento."
T[43717]="Eu desejo que o lindo Lorde Prestor repare em mim! Ele é um sonho!"
T[43718]="Eu desejo ter um grande e glorioso bigode um dia."
T[43719]="Um dia eu serei mais poderosa do que todos esses magos!"
T[43720]="Eu desejo ser transferido de Ventobravo um dia e ver Cersei novamente. Nada de bom acontece nesta cidade."
T[43721]="Vocês magos se recusam a me dar aquilo que poderia adiantar o destino inevitável de duas pessoas apaixonadas, quando só uma delas é teimosa demais para enxergar o amor. Eu desejo a ruína de todos vocês."
T[43723]="Desejo que o capitão Albernaz chegue logo com aquele carregamento de vinho."
T[43724]="Anel? Parece mais um colar! E um daqueles bem pesados!"
T[43726]="O senhor da cripta ainda a carregava, apesar de ter perdido o título há muito tempo, ao passar a servir ao Lich Rei."
T[43821]="Ei... Ainda pulsa!"
T[43823]="Isto virará um belo troféu na parede de alguém."
T[43824]="Contém os segredos para o estudo avançado."
T[43843]="Isso vai servir perfeitamente."
