T[450515]="Ainda brilha com veneno."
T[450521]="Cáries podem deixar qualquer um furioso!"
T[450525]="As lendas falam de um pico solitário onde os relâmpagos caem como um relógio a cada lua cheia. A madeira da varinha veio de uma árvore atingida não uma, mas duas vezes — seu poder agora está entrelaçado nesta relíquia da há muito perdida linhagem Thunderfall."
