T[808965]="Bem feito, duradouro e obtido de forma ética."
T[824385]="Confesso que não sigo filosofia alguma. Pertenço ao mundo real, pois a realidade não cabe em nenhuma ideologia. Essas ideias são abstrações, confortos que abraçamos por medo de fazer perguntas sem a promessa de respostas."
T[824396]="Elmo usado pelos zelotes da Cidade Radiante. Um leve formigamento percorre quem se aproxima. Embora a origem do culto esteja envolta em mistério, alguns sussurram sobre um deus radioativo que apareceu diante de Sua Majestade Radiante e lhe concedeu um propósito divino."
T[824400]="Lança feita com um galho do ninho do Grande Condor. Dizem que os galhos vieram originalmente de uma Árvore do Mundo, derrubada por uma calamidade ainda maior."
