T[1388227]="Antigamente disenhado para proteção a seu portador do dano, este colar foi retorcido por seu proximidade ao Atal'ai."
T[1388369]="Com apenas um cheiro jurarás que o tempo se desacelera. O lhaman uma ensonhação de Pó. Eu o lhamo opções de vidàmentables."
T[1388372]="Perdido em batalha, um berloque tomado pela cobiça esquecida de um pirata."
T[1388374]="O mais requintado exemplo."
T[1388379]="É possível ouvir o mar bem baixinho ao aproximá-la do ouvido."
T[1388479]="Imbuído pelo poder ressonante dos rituais de vínculo com a terra de Martuk, este capuz responde a cada encantamento, chamando rochas e pedras para se erguerem sob seu comando."
T[1388543]="As lendas falam de um pico solitário onde os relâmpagos caem como um relógio a cada lua cheia. A madeira da varinha veio de uma árvore atingida não uma, mas duas vezes — seu poder agora está entrelaçado nesta relíquia da há muito perdida linhagem Thunderfall."
T[1388546]="Você... pegou... veladora?"
T[1388570]="Apenas desejo haver pedido chegar a essa última ilha. O Peixe sempre é mais grande do outro lado."
